import { Field } from '@base-ui/react/field';
import { mergeProps } from '@base-ui/react/merge-props';
import type { ComponentProps, Ref } from 'react';
import { cn } from '../../utils/cn';
import { textareaVariants, type TextareaVariantProps } from './textarea.variants';

type NativeTextareaProps = Omit<ComponentProps<'textarea'>, 'className' | 'ref' | 'value' | 'defaultValue' | 'onChange'>;

export interface TextareaProps extends NativeTextareaProps, TextareaVariantProps {
  className?: string;
  ref?: Ref<HTMLTextAreaElement>;
  value?: string;
  defaultValue?: string;
  onChange?: ComponentProps<'textarea'>['onChange'];
  /** Called with the new string value (mirrors Input's `onValueChange`). */
  onValueChange?: (value: string) => void;
  /** Marks the value as invalid (sets aria-invalid). Inside a Field, `Field invalid` does this. */
  invalid?: boolean;
}

/**
 * Multi-line text input. Renders a native <textarea> through Base UI Field.Control, so a
 * surrounding Field links its label, description and error and tracks dirty/touched state.
 * `autosize` grows the box with its content via CSS `field-sizing: content`.
 */
export function Textarea({
  size,
  resize,
  autosize,
  invalid,
  className,
  ref,
  id,
  name,
  disabled,
  value,
  defaultValue,
  onValueChange,
  rows = 4,
  ...rest
}: TextareaProps) {
  return (
    <Field.Control
      ref={ref as Ref<HTMLElement> | undefined}
      id={id}
      name={name}
      disabled={disabled}
      value={value}
      defaultValue={defaultValue}
      onValueChange={onValueChange ? (v) => onValueChange(v) : undefined}
      render={(controlProps) => (
        <textarea
          {...mergeProps<'textarea'>(controlProps as ComponentProps<'textarea'>, rest, {
            rows: autosize ? undefined : rows,
            'aria-invalid': invalid || undefined,
            className: cn(textareaVariants({ size, resize, autosize }), className),
          })}
        />
      )}
    />
  );
}

export { Textarea, type TextareaProps } from './Textarea';
export { textareaVariants, type TextareaVariantProps } from './textarea.variants';
export { doc as textareaDoc } from './Textarea.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const textareaVariants = tv({
  base: [
    'block w-full min-w-0 rounded-md border border-border bg-background px-3 py-2 text-foreground shadow-sm',
    'placeholder:text-muted-foreground transition-colors motion-reduce:transition-none',
    'focus-visible:border-primary/60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    'data-invalid:border-destructive/70 aria-invalid:border-destructive/70',
    'disabled:cursor-not-allowed disabled:bg-secondary/50 disabled:text-muted-foreground',
    'read-only:bg-secondary/40',
  ],
  variants: {
    size: {
      sm: 'text-[12px] leading-5',
      md: 'text-[13px] leading-6',
    },
    resize: {
      none: 'resize-none',
      vertical: 'resize-y',
    },
    autosize: {
      true: 'field-sizing-content min-h-[88px] resize-none',
      false: '',
    },
  },
  defaultVariants: { size: 'md', resize: 'none', autosize: false },
});

export type TextareaVariantProps = VariantProps<typeof textareaVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Textarea',
  group: 'Forms',
  status: 'stable',
  description: 'Multi-line text input in two sizes, with optional CSS autosize (field-sizing: content) and vertical resize. Renders through Base UI Field.Control, so it works inside Field.',
  primitive: '@base-ui/react/field (Field.Control)',
  pattern: 'textbox (multi-line)',
  keyboard: [
    ['Tab', 'Moves focus into and out of the textarea'],
    ['Enter', 'Inserts a new line (does not submit the form)'],
  ],
  tokens: ['background', 'border', 'foreground', 'muted-foreground', 'primary', 'destructive', 'secondary', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
